    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '201: "High-Sensitivity Troponin" (hs-cTn) assays allow for the detection of myocardial injury _____ than standard assays.', '["Slower", "Earlier (within 1 to 2 hours of symptoms)", "Only after 24 hours", "Equally"]', 1, 'These assays can detect much lower concentrations of troponin.'),
    (v_topic_id, '202: Which cardiac marker is most useful for detecting "Re-infarction" shortly after an initial heart attack?', '["Troponin", "CK-MB (due to its shorter half-life and more rapid return to baseline)", "Myoglobin", "LDH"]', 1, 'Troponin stays high for up to 10 days, making it hard to see a new rise; CK-MB returns to normal in 48-72 hours.'),
    (v_topic_id, '203: "BNP" levels can be "falsely" low in patients who are:', '["Thin", "Obese", "Elderly", "Men"]', 1, 'Obesity is associated with lower circulating levels of natriuretic peptides.'),
    (v_topic_id, '204: "BNP" levels can be "falsely" high in patients with:', '["Renal failure and Advanced age", "Anemia", "Pneumonia", "Normal heart"]', 0, 'BNP is cleared by the kidneys, and levels naturally rise with age.'),
    (v_topic_id, '205: "Glycated Hemoglobin" (HbA1c) may be "falsely low" in patients with:', '["Iron deficiency", "Hemolytic Anemia or recent blood transfusion (due to decreased RBC lifespan)", "Renal failure", "Splenectomy"]', 1, 'Anything that shortens RBC lifespan reduces the time for hemoglobin to become glycated.'),
    (v_topic_id, '206: "Glycated Hemoglobin" (HbA1c) may be "falsely high" in patients with:', '["Iron deficiency anemia (due to increased RBC lifespan)", "Hemolysis", "Pregnancy", "Sickle cell"]', 0, 'Slower RBC turnover allows for more glycation over time.'),
    (v_topic_id, '207: "Fructosamine" measures glycation of _____ and reflects glucose control over the past _____:', '["Hemoglobin; 3 months", "Serum proteins (mostly albumin); 2 to 3 weeks", "Platelets; 10 days", "WBCs; 5 days"]', 1, 'It is useful in patients where HbA1c is unreliable (e.g., hemolytic anemia).'),
    (v_topic_id, '208: "TSH" (Thyroid Stimulating Hormone) is the best _____ test for thyroid function.', '["Confirmation", "Screening", "Synthetic", "Useless"]', 1, 'Small changes in free T4 lead to large, exponential changes in TH.'),
    (v_topic_id, '209: "Subclinical Hypothyroidism" is defined as:', '["Low TSH and Low T4", "High TSH with a NORMAL Free T4", "High TSH and Low T4", "Normal TSH"]', 1, 'The body is maintaining normal T4 levels but at the cost of high TSH stimulation.'),
    (v_topic_id, '210: "Subclinical Hyperthyroidism" is defined as:', '["Low TSH with a NORMAL Free T4", "Low TSH and High T4", "High TSH", "Normal TSH"]', 0, 'The patient may be asymptomatic but at risk for atrial fibrillation or osteoporosis.'),
    (v_topic_id, '211: "Euthyroid Sick Syndrome" (Low T3 Syndrome) is seen in critically ill patients and typically shows:', '["High TSH", "Low T3, with normal or low T4 and TSH", "High T4", "High T3"]', 1, 'This is a physiological adaptation to severe systemic illness.'),
    (v_topic_id, '212: "Serum Cortisol" levels are highest at:', '["Midnight", "8:00 AM (diurnal variation)", "4:00 PM", "Noon"]', 1, 'Cortisol follows a circadian rhythm; a morning level is standard for screening.'),
    (v_topic_id, '213: "Cushing Syndrome" is diagnosed by failure to suppress cortisol after:', '["A high-fat meal", "Low-dose Dexamethasone (1 mg overnight)", "Exercise", "Sleep"]', 1, 'Dexamethasone should normally provide negative feedback and lower cortisol levels.'),
    (v_topic_id, '214: "Addison Disease" (Primary Adrenal Insufficiency) is diagnosed by failure of cortisol to rise after:', '["Dexamethasone", "ACTH (Cosyntropin) stimulation", "Insulin", "Glucose"]', 1, 'The adrenal glands are too damaged to respond to the stimulation signal.'),
    (v_topic_id, '215: "Prostate Specific Antigen" (PSA) can be elevated by:', '["Prostate cancer", "Benign Prostatic Hyperplasia (BPH) or Prostatitis", "Recent digital rectal exam or cycling", "All of the above"]', 3, 'PSA is organ-specific but not cancer-specific.'),
    (v_topic_id, '216: "Free PSA" percentage < 10% is more suggestive of _____ than BPH.', '["Infection", "Prostate Cancer", "Stones", "Diabetes"]', 1, 'Cancer cells tend to produce more bound PSA.'),
    (v_topic_id, '217: "Alpha-fetoprotein" (AFP) is a tumor marker for:', '["Colon cancer", "Hepatocellular Carcinoma (HCC) and certain Germ Cell Tumors", "Prostate cancer", "Lung cancer"]', 1, 'It is also measured in maternal serum to screen for neural tube defects.'),
    (v_topic_id, '218: "Carcinoembryonic Antigen" (CEA) is primarily used to monitor:', '["Prostate cancer", "Colorectal Cancer recurrence", "Pancreatitis", "Breast cancer"]', 1, 'It is not sensitive enough for initial screening but helps track treatment response.'),
    (v_topic_id, '219: "CA-125" is a marker used in the management of _____ cancer.', '["Lung", "Ovarian", "Breast", "Colon"]', 1, 'It can also be elevated in endometriosis or menstruation.'),
    (v_topic_id, '220: "CA 19-9" is a marker for _____ cancer.', '["Pancreatic", "Prostate", "Liver", "Thyroid"]', 0, 'It is also used to monitor treatment response.'),
    (v_topic_id, '221: "hCG" (human Chorionic Gonadotropin) is the marker for pregnancy and:', '["Testicular germ cell tumors or Gestational Trophoblastic Disease", "Anemia", "Diabetes", "Kidney failure"]', 0, 'Extremely high levels suggest a molar pregnancy or choriocarcinoma.'),
    (v_topic_id, '222: "Serum Iron" = 30, TIBC = 450, Ferritin = 5. Diagnosis?', '["Iron Deficiency Anemia", "Anemia of Chronic Disease", "Thalassemia", "Sideroblastic anemia"]', 0, 'The low ferritin and high TIBC are the diagnostic markers for iron deficiency.'),
    (v_topic_id, '223: "Serum Iron" = 30, TIBC = 150, Ferritin = 500. Diagnosis?', '["Iron Deficiency", "Anemia of Chronic Disease (ACD)", "Thalassemia", "Lead poisoning"]', 1, 'Iron is trapped in macrophages (high ferritin), but serum iron and transport capacity (TIBC) are low.'),
    (v_topic_id, '224: "Serum Iron" = 150, TIBC = 250, Ferritin = 1000. Transferrin Saturation = 60%. Diagnosis?', '["Iron deficiency", "Hereditary Hemochromatosis (Iron Overload)", "ACD", "Hemolysis"]', 1, 'High saturation and ferritin are typical for iron overload.'),
    (v_topic_id, '225: "Vanillylmandelic Acid" (VMA) and "Metanephrines" in a 24-hour urine collection are used to diagnose:', '["Diabetes", "Pheochromocytoma (Catecholamine-secreting tumor)", "Renal failure", "Liver failure"]', 1, 'These are the breakdown products of epinephrine and norepinephrine.'),
    (v_topic_id, '226: "5-HIAA" (5-Hydroxyindoleacetic acid) in the urine is the marker for:', '["Gout", "Carcinoid Syndrome (serotonin-producing tumor)", "Pheochromocytoma", "Addison disease"]', 1, 'Serotonin is metabolized to 5-HIAA.'),
    (v_topic_id, '227: "Cerebrospinal Fluid" (CSF) - The "Traumatic Tap" is distinguished from Subarachnoid Hemorrhage (SAH) by:', '["Decrease in RBC count from tube 1 to tube 4", "Presence of xanthochromia", "High protein", "Low glucose"]', 0, 'If the needle caused the bleeding, the count should drop as the fluid clears.'),
    (v_topic_id, '228: "Normal" CSF pressure (measured by opening pressure during LP) is usually:', '["< 5 cm H2O", "10 to 20 cm H2O", "> 30 cm H2O", "50 cm H2O"]', 1, 'Elevated pressure suggests meningitis, tumor, or idiopathic intracranial hypertension.'),
    (v_topic_id, '229: "Albuminocytologic Dissociation" (High Protein with NORMAL WBC count) in the CSF is the classic finding for:', '["Bacterial Meningitis", "Guillain-Barr\u00e9 Syndrome", "Multiple Sclerosis", "Brain abscess"]', 1, 'This suggests inflammation of the nerve roots without a cellular meningeal response.'),
    (v_topic_id, '230: "CSF Glucose" is normally approximately _____ of the concurrent Blood Glucose.', '["10%", "60 to 70%", "100%", "200%"]', 1, 'A level < 40 mg/dL or < 50% of serum glucose is highly suspicious for bacterial meningitis.'),
    (v_topic_id, '231: "Synovial Fluid" - "Group I" (Non-inflammatory) fluid is characteristic of:', '["Osteoarthritis and Trauma", "Gout", "Septic arthritis", "Rheumatoid arthritis"]', 0, 'WBC count is low (< 2,000) and the fluid is clear/straw-colored.'),
    (v_topic_id, '232: "Synovial Fluid" - "Group II" (Inflammatory) fluid (WBC 2,000 - 50,000) is seen in:', '["Gout, Pseudogout, and Rheumatoid Arthritis", "Normal joints", "Severe bacterial infection", "None"]', 0, 'The fluid appears cloudy but is not yet "purulent."'),
    (v_topic_id, '233: "Synovial Fluid" - "Group III" (Septic) fluid (WBC > 50,000) is most often:', '["Yellow", "Purulent (pus-like)", "Clear", "Red"]', 1, 'It requires urgent drainage and antibiotics.'),
    (v_topic_id, '234: "Pleural Fluid" - A "Pleural / Serum Protein" ratio > _____ suggests an EXUDATE.', '["0.1", "0.5", "0.9", "2.0"]', 1, 'This is the first of Light''s criteria.'),
    (v_topic_id, '235: "Pleural Fluid" - A "Pleural / Serum LDH" ratio > _____ suggests an EXUDATE.', '["0.2", "0.6", "1.0", "5.0"]', 1, 'The second of Light''s criteria.'),
    (v_topic_id, '236: "Pleural Fluid" - An absolute LDH level > _____ of the upper limit of normal serum LDH suggests an EXUDATE.', '["1/4", "2/3", "1/2", "All"]', 1, 'The third of Light''s criteria.'),
    (v_topic_id, '237: A "Chylothorax" (lymph in the pleural space) is diagnosed by a Pleural Fluid Triglyceride level of:', '["< 10 mg/dL", "> 110 mg/dL", "Zero", "Normal"]', 1, 'The fluid often looks milky.'),
    (v_topic_id, '238: "Ascites" - The "Serum-Ascites Albumin Gradient" (SAAG) > 1.1 g/dL suggests:', '["Malignancy or Tuberculosis", "Portal Hypertension (e.g., Cirrhosis, Heart failure)", "Pancreatitis", "Nephrotic syndrome"]', 1, 'A high gradient means there is high pressure forcing water out while keeping albumin in the serum.'),
    (v_topic_id, '239: "Ascites" - The "Serum-Ascites Albumin Gradient" (SAAG) < 1.1 g/dL suggests:', '["Cirrhosis", "Peritoneal Carcinomatosis, Tuberculosis, or Pancreatitis", "Heart failure", "Budd-Chiari"]', 1, 'A low gradient means the protein leaked out of the vessels due to inflammation or malignancy.'),
    (v_topic_id, '240: "Spontaneous Bacterial Peritonitis" (SBP) is diagnosed by an ascitic fluid absolute neutrophil count (ANC) of:', '["< 100 /mm3", "> 250 /mm3", "> 1000 /mm3", "Zero"]', 1, 'This indicates infection of pre-existing ascites in a cirrhotic patient.'),
    (v_topic_id, '241: "Pericardial Fluid" is most commonly obtained to diagnose and treat:', '["Heart attack", "Cardiac Tamponade", "Atrial fibrillation", "Valve disease"]', 1, 'Pericardiocentesis is life-saving in tamponade.'),
    (v_topic_id, '242: "Creatine Kinase" (CK) elevation from "Strenuous Exercise" can be distinguished from a heart attack by:', '["Checking Troponin (which should be normal)", "Looking at the patient", "Repeating the test", "Checking glucose"]', 0, 'Exercise increases CK-MM but not cardiac-specific troponins.'),
    (v_topic_id, '243: "High Density Lipoprotein" (HDL) levels can be increased by:', '["Smoking", "Regular Aerobic Exercise", "Obesity", "Trans-fats"]', 1, 'Exercise and moderate alcohol (not recommended as therapy) can raise HDL.'),
    (v_topic_id, '244: "Low Density Lipoprotein" (LDL) targets in patients with existing "Coronary Artery Disease" are often:', '["< 130 mg/dL", "< 70 mg/dL (or even lower)", "200 mg/dL", "160 mg/dL"]', 1, 'Aggressive lowering is indicated for secondary prevention.'),
    (v_topic_id, '245: "Hepatitis B Surface Antigen" (HBsAg) indicates:', '["Immunity", "Active Infection (Acute or Chronic)", "Recovery", "Vaccination"]', 1, 'If present for > 6 months, the infection is considered chronic.'),
    (v_topic_id, '246: "Hepatitis B Surface Antibody" (HBsAb or anti-HBs) indicates:', '["Active infection", "Immunity (from prior infection or vaccination)", "Death", "Liver failure"]', 1, 'This is the "protective" antibody.'),
    (v_topic_id, '247: "Hepatitis B Core Antibody" (HBcAb or anti-HBc) "IgM" indicates:', '["Chronic infection", "Acute infection (Window period)", "Vaccination", "Carrier state"]', 1, 'IgM Core antibody is the only marker positive during the "window period" when HBsAg has disappeared but HBsAb hasn''t appeared yet.'),
    (v_topic_id, '248: "Hepatitis B Core Antibody" (HBcAb) "IgG" indicates:', '["Vaccination", "Past or ongoing infection (NOT seen in vaccinated individuals)", "Acute infection", "No infection"]', 1, 'Vaccinated individuals ONLY have the Surface antibody.'),
    (v_topic_id, '249: "Hepatitis C" is initially screened for using an _____ and confirmed by _____:', '["X-ray; MRI", "Antibody test; HCV RNA (PCR)", "LFTs; Biopsy", "BNP; Troponin"]', 1, 'The antibody test indicates exposure; the RNA test proves current infection.'),
    (v_topic_id, '250: "Hepatitis A" is spread by the _____ route and diagnosed by _____:', '["Blood; MRI", "Fecal-oral; Anti-HAV IgM", "Sexual; Biopsy", "Tick; PCR"]', 1, 'It is usually an acute, self-limiting illness.'),
    (v_topic_id, '251: "Serum Iron" is notoriously unreliable for diagnosing iron deficiency because it:', '["Is too expensive", "Fluctuates significantly throughout the day and with meals", "Only measures free iron", "Never changes"]', 1, 'Ferritin is much more stable.'),
    (v_topic_id, '252: "Soluble Transferrin Receptor" (sTfR) levels are _____ in iron deficiency and _____ in anemia of chronic disease.', '["Low; High", "High; Normal/Low", "Normal; High", "Zero; High"]', 1, 'This is an expensive but useful test to distinguish the two conditions.'),
    (v_topic_id, '253: "Vitamin B12" (Cobalamin) deficiency can lead to irreversible:', '["Heart failure", "Subacute Combined Degeneration of the Spinal Cord", "Kidney stones", "Blindness"]', 1, 'Neurological symptoms may occur even without significant anemia.'),
    (v_topic_id, '254: "Folate" deficiency is similar to B12 but does NOT cause:', '["Macrocytic anemia", "Neurological deficits", "Hypersegmented neutrophils", "High homocysteine"]', 1, 'This is a key clinical differentiator.'),
    (v_topic_id, '255: "Hemoglobin A" is composed of:', '["Two alpha and two beta chains (\u03b12\u03b22)", "Two alpha and two delta chains", "Four beta chains", "Two alpha and two gamma chains"]', 0, 'This is the normal adult hemoglobin.'),
    (v_topic_id, '256: "Hemoglobin A2" is composed of:', '["\u03b12\u03b22", "\u03b12\u03b42 (Two alpha and two delta)", "\u03b12\u03b32", "\u03b24"]', 1, 'It makes up < 3.5% of normal adult hemoglobin.'),
    (v_topic_id, '257: "Hemoglobin F" is composed of:', '["\u03b12\u03b22", "\u03b12\u03b32 (Two alpha and two gamma)", "\u03b24", "\u03b34"]', 1, 'It is the main hemoglobin in the fetus.'),
    (v_topic_id, '258: "Hemoglobin H" disease is a form of Alpha-Thalassemia involving _____ gene deletions.', '["1", "2", "3", "4"]', 2, 'It results in the formation of \u03b24 tetramers.'),
    (v_topic_id, '259: "Hemoglobin Barts" involves the deletion of all four alpha genes and results in _____ tetramers and _____:', '["\u03b34; Hydrops Fetalis (incompatible with life)", "\u03b24; Anemia", "S2; Pain", "\u03b14; Normal life"]', 0, 'The fetus cannot produce any functional hemoglobin.'),
    (v_topic_id, '260: "Osmotic Fragility Test" is used to diagnose:', '["Sickle cell", "Hereditary Spherocytosis", "Iron deficiency", "G6PD deficiency"]', 1, 'Spherocytes burst more easily when placed in hypotonic saline.'),
    (v_topic_id, '261: "Paroxysmal Nocturnal Hemoglobinuria" (PNH) is characterized by hemolysis, pancytopenia, and _____:', '["Bleeding", "Venous Thrombosis (especially in unusual sites like the Budd-Chiari portal veins)", "Kidney stones", "Bone fractures"]', 1, 'It is due to a deficiency of CD55 and CD59 on the RBC surface.'),
    (v_topic_id, '262: The "Flow Cytometry" test for PNH looks for the absence of:', '["CD55 and CD59", "Iron", "DNA", "Factor VIII"]', 0, 'These proteins normally protect the RBC from complement-mediated destruction.'),
    (v_topic_id, '263: "Malaria" smear: The presence of "Banana-shaped" gametocytes is classic for:', '["Plasmodium vivax", "Plasmodium falciparum", "Plasmodium ovale", "Plasmodium malariae"]', 1, 'Falciparum is the most dangerous form of malaria.'),
    (v_topic_id, '264: "Protein Electrophoresis" (SPEP): A "Beta-gamma bridge" is seen in:', '["Multiple Myeloma", "Cirrhosis (due to increased IgA)", "Nephrotic syndrome", "Dehydration"]', 1, 'This is a classic board sign of chronic liver disease.'),
    (v_topic_id, '265: "Protein Electrophoresis" (SPEP): A massive loss of albumin and a relative increase in alpha-2-macroglobulin is seen in:', '["Cirrhosis", "Nephrotic Syndrome", "Malnutrition", "Pregnancy"]', 1, 'The large alpha-2 protein is retained while smaller ones are lost in the urine.'),
    (v_topic_id, '266: "Amylase" can be elevated in which condition besides pancreatitis?', '["Salivary gland inflammation (Mumps)", "Ectopic pregnancy rupture", "Bowel perforation", "All of the above"]', 3, 'Lipase is preferred for pancreatitis because it is not found in the salivary glands.'),
    (v_topic_id, '267: "Creatine Kinase MB" (CK-MB) levels > _____% of the total CK suggest cardiac origin.', '["1%", "5%", "25%", "50%"]', 1, 'Lower percentages usually indicate skeletal muscle source.'),
    (v_topic_id, '268: "Troponin" elevation with NORMAL Coronary Arteries on angiogram is called:', '["A mistake", "MINOCA (Myocardial Infarction with Non-Obstructive Coronary Arteries)", "Pericarditis", "Stroke"]', 1, 'Can be due to spasm, embolism, or microvascular disease.'),
    (v_topic_id, '269: "Free T3" is rarely measured compared to Free T4 because:', '["It is too expensive", "It fluctuates wildly and T4 is the main reservoir that converts to T3 at the tissue level", "It is not active", "It is zero"]', 1, 'TSH and Free T4 are the standard initial duo.'),
    (v_topic_id, '270: "Antimicrosomal" and "Anti-TPO" antibodies are markers for:', '["Graves disease", "Hashimoto Thyroiditis", "Thyroid cancer", "Goiter"]', 1, 'They indicate autoimmune destruction of the thyroid.'),
    (v_topic_id, '271: "Thyroid Stimulating Immunoglobulin" (TSI) is the marker for:', '["Hashimoto", "Graves Disease", "Thyroiditis", "Riedel thyroiditis"]', 1, 'These antibodies mimic TSH and over-stimulate the thyroid.'),
    (v_topic_id, '272: "Thyroglobulin" (Tg) levels are used to monitor for recurrence of _____ after surgery.', '["Graves disease", "Differentiated Thyroid Cancer (Papillary or Follicular)", "Hyperparathyroidism", "Diabetes"]', 1, 'If the thyroid is gone, Tg should be undetectable.'),
    (v_topic_id, '273: "Calcitonin" is a marker for _____ Thyroid Cancer.', '["Papillary", "Follicular", "Medullary (arising from Parafollicular C-cells)", "Anaplastic"]', 2, 'Medullary thyroid cancer is associated with MEN 2A and 2B.'),
    (v_topic_id, '274: "Calcium" and "Phosphate" move in OPPOSITE directions in which condition?', '["Vitamin D deficiency", "Primary Hyperparathyroidism (High Ca, Low PO4)", "Renal failure", "Malabsorption"]', 1, 'PTH promotes calcium reabsorption and phosphate excretion in the kidney.'),
    (v_topic_id, '275: "Calcium" and "Phosphate" both fall in:', '["Hyperparathyroidism", "Vitamin D Deficiency", "Renal failure", "Bone metastasis"]', 1, 'Lack of Vitamin D impairs the absorption of both minerals from the gut.'),
    (v_topic_id, '276: "Secondary Hyperparathyroidism" is a normal response to:', '["High calcium", "Low Calcium or High Phosphate (e.g., in Chronic Kidney Disease)", "High TSH", "Exercise"]', 1, 'The parathyroid glands overwork to try and correct the calcium/phosphate balance.'),
    (v_topic_id, '277: "Primary Hyperaldosteronism" (Conn Syndrome) presents with:', '["Hypokalemia, Hypertension, and High Aldosterone with LOW Renin", "High Renin", "Low BP", "Low Aldosterone"]', 0, 'Excess aldosterone suppresses the renin-angiotensin system via negative feedback.'),
    (v_topic_id, '278: "Secondary Hyperaldosteronism" (e.g., from Renal Artery Stenosis) presents with:', '["Low Renin", "High Aldosterone and HIGH Renin", "Low BP", "Normal electrolytes"]', 1, 'The kidney "thinks" the body is hypotensive and triggers the entire RAAS.'),
    (v_topic_id, '279: "Serum Cortisol" of < 3 mcg/dL in the morning is highly suggestive of:', '["Cushing syndrome", "Adrenal Insufficiency", "Normal state", "Diabetes"]', 1, 'Levels should normally be much higher at 8:00 AM.'),
    (v_topic_id, '280: "24-hour Urinary Free Cortisol" is a useful test for:', '["Adrenal insufficiency", "Cushing Syndrome (screens for over-production)", "Diabetes", "Renal failure"]', 1, 'It integrates cortisol production over a whole day.'),
    (v_topic_id, '281: "Sweat Chloride Test" is the gold standard for diagnosing:', '["Diabetes", "Cystic Fibrosis", "Renal failure", "Adrenal insufficiency"]', 1, 'Defective CFTR channels lead to abnormally salty sweat.'),
    (v_topic_id, '282: "Urea Breath Test" is used to diagnose infection with:', '["Streptococcus", "Helicobacter pylori", "E. coli", "Salmonella"]', 1, 'H. pylori produces urease, which breaks down the labeled urea swallowed by the patient.'),
    (v_topic_id, '283: "Stool Osmotic Gap" > 100 mOsm/kg suggests:', '["Secretory diarrhea", "Osmotic diarrhea (e.g., Lactose intolerance or Laxative use)", "Infection", "Normal stool"]', 1, 'Gap = 290 - 2([Na] + [K]) in the stool water.'),
    (v_topic_id, '284: "Stool Osmotic Gap" < 50 mOsm/kg suggests:', '["Osmotic diarrhea", "Secretory diarrhea (e.g., Cholera or VIPoma)", "Constipation", "Normal"]', 1, 'The electrolytes themselves are causing the diarrhea.'),
    (v_topic_id, '285: "Fecal Calprotectin" is a marker used to distinguish:', '["Infection from Cancer", "Inflammatory Bowel Disease (IBD) from Irritable Bowel Syndrome (IBS)", "Fat from Protein", "Blood from Mucus"]', 1, 'Calprotectin is released by neutrophils in the gut wall.'),
    (v_topic_id, '286: "Fecal Fat" (72-hour collection) is the gold standard for diagnosing:', '["Infection", "Malabsorption / Steatorrhea", "Constipation", "Ulcers"]', 1, 'Normal is < 7 grams per day.'),
    (v_topic_id, '287: "D-xylose Test" is used to distinguish malabsorption due to _____ from _____:', '["Pancreatic insufficiency; Mucosal disease (e.g., Celiac Disease)", "Liver disease; Kidney disease", "Sugar; Fat", "Bacterial; Viral"]', 0, 'D-xylose is a simple sugar that requires an intact mucosa for absorption but no pancreatic enzymes.'),
    (v_topic_id, '288: "Celiac Disease" screening is best performed with which antibody?', '["ANA", "Anti-Tissue Transglutaminase (tTG) IgA", "Anti-DNA", "RF"]', 1, 'Patients must also be checked for total IgA deficiency, which can cause false negatives.'),
    (v_topic_id, '289: "Lactose Tolerance Test" is considered positive if blood glucose _____ after drinking lactose.', '["Rises by > 20 mg/dL", "Fails to rise by > 20 mg/dL (indicating lack of absorption)", "Falls", "Stays the same"]', 1, 'Lactose should be broken down into glucose and galactose by lactase.'),
    (v_topic_id, '290: "Hydrogen Breath Test" is used to diagnose:', '["Lactose intolerance and Small Intestinal Bacterial Overgrowth (SIBO)", "Diabetes", "Lung cancer", "Heart failure"]', 0, 'Bacteria in the gut produce hydrogen gas when they ferment unabsorbed sugars.'),
    (v_topic_id, '291: "Lead" poisoning in adults most commonly affects the _____ and _____ systems.', '["Heart and Lung", "Neurological (peripheral neuropathy) and Hematological (anemia)", "Digestive", "Skin"]', 1, 'Classic "Wrist drop" and "Lead lines" on gums.'),
    (v_topic_id, '292: "Ceruloplasmin" levels are LOW in:', '["Hemochromatosis", "Wilson Disease (Copper overload)", "Lead poisoning", "Iron deficiency"]', 1, 'The liver fails to produce the copper-binding protein correctly.'),
    (v_topic_id, '293: "Kayser-Fleischer Rings" in the eye are a sign of _____ and are best seen with _____:', '["Lead; Slit lamp", "Copper deposition (Wilson Disease); Slit lamp examination", "Iron; Flashlight", "Sugar; MRI"]', 1, 'Brownish rings at the periphery of the cornea.'),
    (v_topic_id, '294: "Alpha-1 Antitrypsin" deficiency can lead to _____ and _____:', '["Heart and Brain disease", "Early-onset Emphysema and Liver Cirrhosis", "Diabetes and HTN", "Skin and Bone disease"]', 1, 'The misfolded protein accumulates in the liver and is missing from the lungs.'),
    (v_topic_id, '295: "Cystic Fibrosis" (CF) is caused by a mutation in the _____ channel.', '["Sodium", "Chloride (CFTR)", "Potassium", "Calcium"]', 1, 'This leads to thick, sticky mucus in the lungs and pancreas.'),
    (v_topic_id, '296: "Vitamin D" status is best assessed by measuring:', '["1,25-dihydroxyvitamin D", "25-hydroxyvitamin D (calcidiol)", "Serum Calcium", "Serum Phosphorus"]', 1, '25-OH Vitamin D has a longer half-life and better reflects total stores.'),
    (v_topic_id, '297: "Parathyroid Hormone" (PTH) is an _____ hormone that _____ serum calcium.', '["Anabolic; lowers", "Anabolic; raises (by acting on bone, kidney, and gut indirectly)", "Catabolic; lowers", "Zero; no effect"]', 1, 'It increases bone resorption and renal reabsorption of calcium.'),
    (v_topic_id, '298: "Calcitonin" is a hormone that _____ serum calcium and is produced by _____:', '["Raises; Thyroid", "Lowers; Parafollicular C-cells of the thyroid", "Lowers; Parathyroid", "Raises; Kidney"]', 1, 'Its physiological role in humans is minor, but it is a useful tumor marker.'),
    (v_topic_id, '299: "Osteocalcin" is a marker of:', '["Bone resorption", "Bone formation (osteoblast activity)", "Bone strength", "Bone weight"]', 1, 'Used to monitor osteoporosis treatment.'),
    (v_topic_id, '300: "N-telopeptide" (NTx) and "C-telopeptide" (CTx) in the urine or serum are markers of:', '["Bone formation", "Bone resorption (osteoclast activity)", "Muscle damage", "Kidney function"]', 1, 'They are breakdown products of Type 1 collagen.');
